from datetime import datetime, timedelta
from typing import Dict, List


class _Appointment:
    def __init__(self, appt_id: int, patient: str, doctor: str, start: datetime, end: datetime):
        self.id = appt_id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end
        self.is_cancelled = False


class _BlockedSlot:
    def __init__(self, doctor: str, start: datetime, end: datetime):
        self.doctor = doctor
        self.start = start
        self.end = end


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: Dict[int, _Appointment] = {}
        self._blocked_slots: List[_BlockedSlot] = []

    def book(
        self, patient: str, doctor: str, start: datetime, end: datetime, now: datetime
    ) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start >= end:
            raise ValueError("Start time must be strictly before end time.")

        # Requirement 3: Booking an appointment that starts before `now` raises ValueError.
        if start < now:
            raise ValueError("Cannot book an appointment in the past.")

        # Requirement 1: A patient can have at most one upcoming appointment.
        for appt in self._appointments.values():
            if not appt.is_cancelled and appt.patient == patient:
                # An appointment is upcoming if its end time (or start time) is in the future relative to `now`.
                # Typically, upcoming means start >= now or end > now. Since start >= now is enforced
                # for newly booked ones, any active appointment starting >= now is upcoming.
                if appt.start >= now:
                    raise ValueError(f"Patient '{patient}' already has an upcoming appointment.")

        # Check doctor availability
        if not self.is_free(doctor, start, end):
            raise ValueError(f"Doctor '{doctor}' is not available for the requested time slot.")

        appt_id = self._next_id
        self._next_id += 1

        self._appointments[appt_id] = _Appointment(appt_id, patient, doctor, start, end)
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise KeyError(f"Appointment ID {appointment_id} does not exist.")

        appt = self._appointments[appointment_id]
        if appt.is_cancelled:
            raise ValueError(f"Appointment ID {appointment_id} is already cancelled.")

        appt.is_cancelled = True

        # Requirement 2: Cancelling an appointment less than 24 hours before its start
        # does not free the time slot; the slot stays blocked.
        if appt.start - now < timedelta(hours=24):
            self._blocked_slots.append(_BlockedSlot(appt.doctor, appt.start, appt.end))

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            raise ValueError("Start time must be strictly before end time.")

        # Requirement 4: Appointments that only touch do not overlap.
        # Intervals [start, end) and [s, e) overlap if and only if max(start, s) < min(end, e)
        # which is equivalent to start < e and end > s.

        # Check active appointments for this doctor
        for appt in self._appointments.values():
            if not appt.is_cancelled and appt.doctor == doctor:
                if start < appt.end and end > appt.start:
                    return False

        # Check slots blocked by late cancellations
        for slot in self._blocked_slots:
            if slot.doctor == doctor:
                if start < slot.end and end > slot.start:
                    return False

        return True
